(window.__quranSurahs=window.__quranSurahs||{})[82]={"nomPhon":"Al-Infitaar","versets":{"1":{"text":"Quand le ciel se rompra,","arabe":"إِذَا ٱلسَّمَآءُ ٱنفَطَرَتْ"},"2":{"text":"et que les étoiles se disperseront,","arabe":"وَإِذَا ٱلْكَوَاكِبُ ٱنتَثَرَتْ"},"3":{"text":"et que les mers confondront leurs eaux,","arabe":"وَإِذَا ٱلْبِحَارُ فُجِّرَتْ"},"4":{"text":"et que les tombeaux seront bouleversés,","arabe":"وَإِذَا ٱلْقُبُورُ بُعْثِرَتْ"},"5":{"text":"toute âme saura alors ce qu'elle a accompli et ce qu'elle a remis de faire à plus tard.","arabe":"عَلِمَتْ نَفْسٌۭ مَّا قَدَّمَتْ وَأَخَّرَتْ"},"6":{"text":"O homme! Qu'est-ce qui t'a trompé au sujet de ton Seigneur, le Noble,","arabe":"يَٰٓأَيُّهَا ٱلْإِنسَٰنُ مَا غَرَّكَ بِرَبِّكَ ٱلْكَرِيمِ"},"7":{"text":"qui t'a créé, puis modelé et constitué harmonieusement?","arabe":"ٱلَّذِى خَلَقَكَ فَسَوَّىٰكَ فَعَدَلَكَ"},"8":{"text":"Il t'a façonné dans la forme qu'Il a voulue.","arabe":"فِىٓ أَىِّ صُورَةٍۢ مَّا شَآءَ رَكَّبَكَ"},"9":{"text":"Non...! [malgré tout] vous traitez la Rétribution de mensonge;","arabe":"كَلَّا بَلْ تُكَذِّبُونَ بِٱلدِّينِ"},"10":{"text":"alors que veillent sur vous des gardiens,","arabe":"وَإِنَّ عَلَيْكُمْ لَحَٰفِظِينَ"},"11":{"text":"de nobles scribes,","arabe":"كِرَامًۭا كَٰتِبِينَ"},"12":{"text":"qui savent ce que vous faites.","arabe":"يَعْلَمُونَ مَا تَفْعَلُونَ"},"13":{"text":"Les bons seront, certes, dans un [jardin] de délice,","arabe":"إِنَّ ٱلْأَبْرَارَ لَفِى نَعِيمٍۢ"},"14":{"text":"et les libertins seront, certes, dans une fournaise","arabe":"وَإِنَّ ٱلْفُجَّارَ لَفِى جَحِيمٍۢ"},"15":{"text":"où ils brûleront, le jour de la Rétribution","arabe":"يَصْلَوْنَهَا يَوْمَ ٱلدِّينِ"},"16":{"text":"incapables de s'en échapper.","arabe":"وَمَا هُمْ عَنْهَا بِغَآئِبِينَ"},"17":{"text":"Et qui te dira ce qu'est le jour de la Rétribution?","arabe":"وَمَآ أَدْرَىٰكَ مَا يَوْمُ ٱلدِّينِ"},"18":{"text":"Encore une fois, qui te dira ce qu'est le jour de la Rétribution?","arabe":"ثُمَّ مَآ أَدْرَىٰكَ مَا يَوْمُ ٱلدِّينِ"},"19":{"text":"Le jour où aucune âme ne pourra rien en faveur d'une autre âme. Et ce jour-là, le commandement sera à Allah.","arabe":"يَوْمَ لَا تَمْلِكُ نَفْسٌۭ لِّنَفْسٍۢ شَيْـًۭٔا ۖ وَٱلْأَمْرُ يَوْمَئِذٍۢ لِّلَّهِ"}}};